import React, { useEffect, useState } from 'react';
import { UNIVERSITY_LOGO, getCampusFallbackImage } from '../constants/universityAssets';

/**
 * College card banner: campus photo when no custom image; logo only as last resort.
 */
const CollegeCardImage = ({ name, image, collegeId = 0 }) => {
  const campusFallback = getCampusFallbackImage(collegeId);
  const hasCustomImage = Boolean(image);

  const [src, setSrc] = useState(hasCustomImage ? image : campusFallback);
  const [useLogoFallback, setUseLogoFallback] = useState(false);

  useEffect(() => {
    setUseLogoFallback(false);
    setSrc(hasCustomImage ? image : campusFallback);
  }, [image, collegeId, campusFallback, hasCustomImage]);

  const handleError = () => {
    if (src === UNIVERSITY_LOGO) return;
    if (src !== campusFallback && hasCustomImage) {
      setSrc(campusFallback);
      return;
    }
    setUseLogoFallback(true);
    setSrc(UNIVERSITY_LOGO);
  };

  return (
    <div
      className={`absolute inset-0 ${
        useLogoFallback ? 'flex items-center justify-center bg-gray-50 dark:bg-slate-800' : ''
      }`}
    >
      <img
        src={src}
        alt={name}
        className={
          useLogoFallback
            ? 'h-32 w-32 object-contain p-4'
            : 'h-full w-full object-cover transition-transform duration-1000 group-hover:scale-110'
        }
        onError={handleError}
      />
    </div>
  );
};

export default CollegeCardImage;
export { UNIVERSITY_LOGO } from '../constants/universityAssets';

// FIXED [Phase 7.2]: Header global search with grouped results
import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, Loader2, Users, GraduationCap, BookOpen, Building2, Layers } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import searchService from '../../services/search.service';

const GlobalSearch = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [query, setQuery] = useState('');
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState(null);
  const wrapRef = useRef(null);

  const runSearch = useCallback(async (q) => {
    if (q.trim().length < 2) {
      setResults(null);
      return;
    }
    try {
      setLoading(true);
      const res = await searchService.globalSearch(q.trim());
      if (res.success) setResults(res.data);
    } catch (err) {
      console.error('Global search failed:', err);
      setResults({ students: [], doctors: [], courses: [], colleges: [], departments: [] });
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => runSearch(query), 300);
    return () => clearTimeout(timer);
  }, [query, runSearch]);

  useEffect(() => {
    const onDoc = (e) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target)) setOpen(false);
    };
    document.addEventListener('mousedown', onDoc);
    return () => document.removeEventListener('mousedown', onDoc);
  }, []);

  const go = (path) => {
    navigate(path);
    setOpen(false);
    setQuery('');
    setResults(null);
  };

  const sections = results
    ? [
        {
          key: 'students',
          label: t('nav.students'),
          icon: Users,
          items:
            results.students?.map((s) => ({
              id: s.id,
              title: `${s.firstName} ${s.lastName}`,
              meta: s.studentId,
              path: `/students/${s.id}`,
            })) || [],
        },
        {
          key: 'doctors',
          label: t('nav.doctors'),
          icon: GraduationCap,
          items:
            results.doctors?.map((d) => ({
              id: d.id,
              title: `${d.firstName} ${d.lastName}`,
              meta: d.doctorId,
              path: '/doctors',
            })) || [],
        },
        {
          key: 'courses',
          label: t('nav.courses'),
          icon: BookOpen,
          items:
            results.courses?.map((c) => ({
              id: c.id,
              title: c.name,
              meta: c.courseCode,
              path: `/courses/${c.id}`,
            })) || [],
        },
        {
          key: 'colleges',
          label: t('nav.colleges'),
          icon: Building2,
          items:
            results.colleges?.map((c) => ({
              id: c.id,
              title: c.name,
              path: `/colleges/${c.id}`,
            })) || [],
        },
        {
          key: 'departments',
          label: t('nav.departments'),
          icon: Layers,
          items:
            results.departments?.map((d) => ({
              id: d.id,
              title: d.name,
              meta: d.college?.name,
              path: `/departments/${d.id}`,
            })) || [],
        },
      ].filter((s) => s.items.length > 0)
    : [];

  const showPanel = open && query.trim().length >= 2;

  return (
    <div ref={wrapRef} className="relative hidden max-w-md md:block group w-80">
      <Search className="absolute left-4 rtl:left-auto rtl:right-4 top-1/2 h-4 w-4 -translate-y-1/2 text-brand-text-muted group-focus-within:text-brand-primary-500 transition-colors" />
      <input
        type="search"
        value={query}
        onChange={(e) => {
          setQuery(e.target.value);
          setOpen(true);
        }}
        onFocus={() => setOpen(true)}
        placeholder={t('search.placeholder')}
        className="h-11 w-full rounded-2xl border border-brand-border bg-surface-subtle pl-11 pr-4 rtl:pl-4 rtl:pr-11 text-sm text-brand-text-primary transition-all placeholder:text-brand-text-muted focus:border-brand-primary-500 focus:bg-brand-bg-card focus:outline-none focus:ring-4 focus:ring-brand-primary-500/10"
        aria-expanded={showPanel}
        aria-autocomplete="list"
      />

      {showPanel && (
        <div className="absolute top-full mt-2 w-full max-h-[24rem] overflow-y-auto rounded-2xl border border-brand-border bg-brand-bg-card shadow-elevated z-50 custom-scrollbar">
          {loading ? (
            <div className="flex items-center justify-center gap-2 py-8 text-brand-text-muted">
              <Loader2 className="animate-spin" size={20} />
              <span className="text-sm font-bold">{t('search.searching')}</span>
            </div>
          ) : sections.length === 0 ? (
            <p className="py-8 text-center text-sm font-bold text-brand-text-muted">
              {t('search.noResults')}
            </p>
          ) : (
            sections.map((section) => (
              <div key={section.key} className="border-b border-brand-border last:border-0">
                <p className="px-4 py-2 text-[10px] font-black uppercase tracking-widest text-brand-text-muted flex items-center gap-2">
                  <section.icon size={12} /> {section.label}
                </p>
                {section.items.map((item) => (
                  <button
                    key={`${section.key}-${item.id}`}
                    type="button"
                    onClick={() => go(item.path)}
                    className="w-full text-start px-4 py-2.5 hover:bg-surface-subtle transition-colors"
                  >
                    <p className="text-sm font-bold text-brand-text-main truncate">{item.title}</p>
                    {item.meta && (
                      <p className="text-xs text-brand-text-muted font-semibold truncate">
                        {item.meta}
                      </p>
                    )}
                  </button>
                ))}
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
};

export default GlobalSearch;

import React, { useState, useRef, useEffect } from 'react';
import { useAuth } from '../../context/AuthContext';
import {
  Bell,
  ChevronDown,
  ChevronRight,
  LogOut,
  User as UserIcon,
  Menu,
  Settings,
} from 'lucide-react';
import ThemeToggle from '../ui/ThemeToggle';
import { useNotifications } from '../../context/NotificationContext';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import LanguageToggle from '../ui/LanguageToggle';
import { useLanguage } from '../../context/LanguageContext';
import GlobalSearch from './GlobalSearch';

const Header = ({ onMenuClick }) => {
  const { user, logout } = useAuth();
  const { notifications, unreadCount, markAsRead, markAllAsRead } = useNotifications();
  const { t } = useTranslation();
  const { isRTL } = useLanguage();
  const navigate = useNavigate();
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);
  const profileRef = useRef(null);
  const notificationsRef = useRef(null);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (profileRef.current && !profileRef.current.contains(event.target)) {
        setIsProfileOpen(false);
      }
      if (notificationsRef.current && !notificationsRef.current.contains(event.target)) {
        setIsNotificationsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const getInitials = () => {
    if (!user) return '?';
    if (user.firstName && user.lastName) {
      return `${user.firstName[0]}${user.lastName[0]}`.toUpperCase();
    }
    return user.email.substring(0, 2).toUpperCase();
  };

  return (
    <header className="sticky top-0 z-30 flex h-16 w-full items-center justify-between border-b border-brand-border bg-brand-bg-card/90 px-4 backdrop-blur-xl md:px-8 transition-colors duration-300">
      <div className="flex items-center gap-6">
        <button
          onClick={onMenuClick}
          className="rounded-xl p-2 text-brand-text-primary dark:text-brand-text-main hover:bg-slate-100 dark:hover:bg-slate-800 md:hidden transition-colors"
          aria-label={t('nav.openMenu')}
        >
          <Menu size={22} />
        </button>

        <GlobalSearch />
      </div>

      <div className="flex items-center gap-2 md:gap-4">
        <LanguageToggle />

        <ThemeToggle />

        <div className="relative" ref={notificationsRef}>
          <button
            onClick={() => setIsNotificationsOpen(!isNotificationsOpen)}
            className="relative rounded-xl p-2 text-brand-text-secondary dark:text-brand-text-main hover:bg-slate-100 dark:hover:bg-slate-800 transition-all"
            aria-label={t('header.notifications')}
            aria-expanded={isNotificationsOpen}
          >
            <Bell size={20} />
            {unreadCount > 0 && (
              <span className="absolute right-2 rtl:right-auto rtl:left-2 top-2 flex h-4 w-4 items-center justify-center rounded-full bg-brand-primary-500 text-[10px] font-black text-white ring-2 ring-brand-bg-card shadow-sm">
                {unreadCount}
              </span>
            )}
          </button>

          {isNotificationsOpen && (
            <div
              className={`fixed inset-x-2 top-20 z-50 md:absolute md:inset-x-auto ${isRTL ? 'md:left-0' : 'md:right-0'} md:top-full mt-3 w-[calc(100vw-2rem)] md:w-96 origin-top-right rounded-[2rem] border border-brand-border bg-brand-bg-card shadow-elevated ring-1 ring-black/5 animate-in fade-in slide-in-from-top-4 duration-300`}
            >
              <div className="flex items-center justify-between border-b border-brand-border px-6 py-5">
                <h3 className="text-base font-black text-brand-text-primary dark:text-brand-text-main uppercase tracking-widest">
                  {t('header.notifications')}
                </h3>
                {unreadCount > 0 && (
                  <button
                    onClick={() => markAllAsRead()}
                    className="label-stat text-brand-primary-500 hover:text-brand-primary-600 transition-colors font-bold"
                  >
                    {t('header.markAllRead')}
                  </button>
                )}
              </div>
              <div className="max-h-[60vh] md:max-h-[32rem] overflow-y-auto py-2 custom-scrollbar">
                {notifications.length === 0 ? (
                  <div className="py-12 text-center">
                    <div className="w-16 h-16 bg-slate-50 dark:bg-slate-800 rounded-3xl flex items-center justify-center mx-auto mb-4 border border-brand-border">
                      <Bell className="h-8 w-8 text-brand-text-muted" />
                    </div>
                    <p className="text-sm font-bold text-brand-text-secondary">
                      {t('header.noNotifications')}
                    </p>
                  </div>
                ) : (
                  notifications.map((notification) => (
                    <div
                      key={notification.id}
                      className={`px-6 py-4 transition-all hover:bg-slate-50 dark:hover:bg-slate-800/50 cursor-pointer border-b border-brand-border last:border-0 ${!notification.isRead ? 'bg-brand-primary-500/5' : ''}`}
                      onClick={() => markAsRead(notification.id)}
                    >
                      <div className="flex gap-4">
                        <div
                          className={`mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full shadow-sm ${!notification.isRead ? 'bg-brand-primary-500 animate-pulse' : 'bg-slate-200 dark:bg-slate-700'}`}
                        />
                        <div>
                          <p className="text-sm font-black text-brand-text-primary dark:text-brand-text-main leading-tight">
                            {notification.title}
                          </p>
                          <p className="text-xs text-brand-text-secondary font-medium mt-1 line-clamp-2 leading-relaxed">
                            {notification.message}
                          </p>
                          <p className="text-[10px] text-brand-text-muted font-bold mt-2 uppercase tracking-wider">
                            {new Date(notification.createdAt).toLocaleTimeString([], {
                              hour: '2-digit',
                              minute: '2-digit',
                            })}
                          </p>
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
              {notifications.length > 0 && (
                <div className="border-t border-brand-border p-4 bg-slate-50/50 dark:bg-slate-800/30">
                  <button
                    onClick={() => {
                      navigate('/notifications');
                      setIsNotificationsOpen(false);
                    }}
                    className="label-stat text-brand-primary-500 hover:text-brand-primary-600 transition-colors flex items-center justify-center gap-2 mx-auto"
                  >
                    {t('header.viewAllNotifications')}{' '}
                    <ChevronRight size={14} className="rtl:-scale-x-100" />
                  </button>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="relative" ref={profileRef}>
          <button
            onClick={() => setIsProfileOpen(!isProfileOpen)}
            className="flex items-center gap-3 rounded-2xl border border-brand-border bg-slate-50 dark:bg-slate-800/30 p-1.5 pr-4 rtl:pl-4 rtl:pr-1.5 transition-all hover:border-brand-primary-500/50 hover:bg-brand-bg-card shadow-sm"
          >
            <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-brand-primary-500 font-black text-white shadow-lg shadow-brand-primary-500/20 ring-2 ring-brand-bg-card transition-transform group-hover:scale-105">
              {user?.profilePicture ? (
                <img
                  src={user.profilePicture}
                  alt="Avatar"
                  className="h-full w-full rounded-xl object-cover"
                />
              ) : (
                getInitials()
              )}
            </div>
            <div className="flex flex-col items-end">
              <span className="text-sm font-black text-brand-text-primary dark:text-brand-text-main truncate max-w-[120px]">
                {user?.firstName} {user?.lastName}
              </span>
              <span className="text-[10px] font-black text-brand-primary-500 uppercase tracking-tighter">
                {user?.role?.replace('_', ' ')}
              </span>
            </div>
            <ChevronDown
              size={16}
              className={`text-brand-text-muted transition-transform duration-300 ${isProfileOpen ? 'rotate-180' : ''} ${isRTL ? 'rotate-180' : ''}`}
            />
          </button>

          {isProfileOpen && (
            <div
              className={`absolute ${isRTL ? 'left-0' : 'right-0'} mt-3 w-64 origin-top-right rounded-[2rem] border border-brand-border bg-brand-bg-card p-2 shadow-elevated ring-1 ring-black/5 animate-in fade-in zoom-in-95 duration-200`}
            >
              <div className="px-4 py-4 mb-2 border-b border-brand-border">
                <p className="label-stat text-brand-text-muted mb-1">{t('header.signedInAs')}</p>
                <p className="text-sm font-black text-brand-text-primary dark:text-brand-text-main truncate">
                  {user?.email}
                </p>
              </div>
              <button
                onClick={() => {
                  navigate('/profile');
                  setIsProfileOpen(false);
                }}
                className="flex w-full items-center gap-3 px-4 py-3 text-sm font-bold text-brand-text-primary dark:text-brand-text-main hover:bg-brand-primary-500 hover:text-white rounded-2xl transition-all group"
              >
                <div className="w-8 h-8 rounded-lg bg-slate-100 dark:bg-slate-800 flex items-center justify-center group-hover:bg-white/20 transition-colors">
                  <UserIcon
                    size={18}
                    className="text-brand-text-secondary group-hover:text-white"
                  />
                </div>
                <span className="label-stat">{t('nav.profile')}</span>
              </button>
              <button
                onClick={() => {
                  navigate('/settings');
                  setIsProfileOpen(false);
                }}
                className="flex w-full items-center gap-3 px-4 py-3 text-sm font-bold text-brand-text-primary dark:text-brand-text-main hover:bg-brand-primary-500 hover:text-white rounded-2xl transition-all group"
              >
                <div className="w-8 h-8 rounded-lg bg-slate-100 dark:bg-slate-800 flex items-center justify-center group-hover:bg-white/20 transition-colors">
                  <Settings
                    size={18}
                    className="text-brand-text-secondary group-hover:text-white"
                  />
                </div>
                <span className="label-stat">{t('nav.settings')}</span>
              </button>
              <div className="my-2 border-t border-brand-border" />
              <button
                onClick={handleLogout}
                className="flex w-full items-center gap-3 px-4 py-3 text-sm font-bold text-error hover:bg-error hover:text-white rounded-2xl transition-all group"
              >
                <div className="w-8 h-8 rounded-lg bg-error/10 flex items-center justify-center group-hover:bg-white/20 transition-colors">
                  <LogOut size={18} className="rtl:-scale-x-100" />
                </div>
                <span className="label-stat">{t('nav.logout')}</span>
              </button>
            </div>
          )}
        </div>
      </div>
    </header>
  );
};

export default Header;

