          },
          {
            title: 'nav.courses',
            path: '/courses',
            icon: BookOpen,
            roles: ['SUPER_ADMIN', 'ADMIN', 'DOCTOR', 'STUDENT'],
          },
          {
            title: 'nav.schedule',
            path: '/schedule',
            icon: Calendar,
            roles: ['SUPER_ADMIN', 'ADMIN', 'DOCTOR', 'STUDENT'],
          },
          { title: 'nav.mySchedule', path: '/schedules/doctor', icon: Calendar, roles: ['DOCTOR'] },
          {
            title: 'nav.mySchedule',
            path: '/schedules/student',
            icon: Calendar,
            roles: ['STUDENT'],
