            title: 'nav.students',
            path: '/students',
            icon: GraduationCap,
            roles: ['SUPER_ADMIN', 'ADMIN', 'COLLEGE_ADMIN', 'DEPARTMENT_ADMIN'],
          },
          {
            title: 'nav.doctors',
            path: '/doctors',
            icon: Users,
            roles: ['SUPER_ADMIN', 'ADMIN', 'COLLEGE_ADMIN', 'DEPARTMENT_ADMIN'],
          },
          {
            title: 'nav.admins',
            path: '/admins',
            icon: ShieldCheck,
            roles: ['SUPER_ADMIN', 'ADMIN'],
          },
        ],
