// FIXED: Session init vs login loading; parse standardized API errors - login fix
import React, { createContext, useState, useEffect, useContext, useCallback } from 'react';
import api, { setAccessToken } from '../services/api';

export interface User {
  id: string;
  email: string;
  role: string;
  firstName?: string;
  lastName?: string;
  twoFactorEnabled?: boolean;
  [key: string]: Record<string, unknown>;
}

export interface AuthContextType {
  user: User | null;
  setUser: React.Dispatch<React.SetStateAction<User | null>>;
  token: string | null;
  loading: boolean;
  error: string | null;
  login: (
    email: string,
    password: string,
    totpToken?: string | null
  ) => Promise<{
    success: boolean;
    user?: User;
    requires2FA?: boolean;
    message?: string;
    status?: number;
  }>;
  register: (data: Record<string, unknown>) => Promise<{ success: boolean; message: string }>;
  logout: () => void;
  isAuthenticated: boolean;
}

const AuthContext = createContext<AuthContextType | null>(null);

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within AuthProvider');
  return context;
};

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [token, setToken] = useState<string | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  const logout = useCallback(async () => {
    try {
      await api.post('/auth/logout');
    } catch (err) {
      console.error('Logout API call failed:', err);
    } finally {
      localStorage.removeItem('user');
      setToken(null);
      setUser(null);
      setError(null);
    }
  }, []);

  const initAuth = useCallback(async () => {
    setLoading(true);
    try {
      // Try to get a new access token via the httpOnly refresh cookie
      const refreshResponse = await api.post('/auth/refresh');
      const { accessToken } = refreshResponse.data.data;
      setToken(accessToken);

      // Now fetch the user profile
      const meResponse = await api.get('/auth/me');
      const me = meResponse.data.data;
      setUser({ ...me, twoFactorEnabled: Boolean(me.twoFactorEnabled) });
    } catch (_err) {
      // No valid refresh cookie — user must log in
      setToken(null);
      setUser(null);
      localStorage.removeItem('user');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    initAuth();
  }, [initAuth]);

  useEffect(() => {
    setAccessToken(token);
  }, [token]);

  const login = async (email: string, password: string, totpToken: string | null = null) => {
    try {
      setError(null);
      const normalizedEmail = email.trim().toLowerCase();
      const response = await api.post('/auth/login', {
        email: normalizedEmail,
        password,
        totpToken,
      });

      if (response.data.requires2FA) {
        return { success: false, requires2FA: true };
      }

      const { accessToken, user: userData } = response.data.data;

      const normalizedUser = {
        ...userData,
        twoFactorEnabled: Boolean(userData.twoFactorEnabled),
      };
      setToken(accessToken);
      setUser(normalizedUser);
      localStorage.setItem('user', JSON.stringify(normalizedUser));
      setLoading(false);

      return { success: true, user: normalizedUser };
    } catch (err: Record<string, unknown>) {
      const message = err.message || 'Login failed';
      const status = err.status;
      setError(message);
      return { success: false, message, status };
    }
  };

  const register = async (data: Record<string, unknown>) => {
    try {
      setLoading(true);
      setError(null);
      const response = await api.post('/auth/register', data);
      return { success: true, message: response.data.message };
    } catch (err: Record<string, unknown>) {
      const message = err.message || 'Registration failed';
      setError(message);
      return { success: false, message };
    } finally {
      setLoading(false);
    }
  };

  const value: AuthContextType = {
    user,
    setUser,
    token,
    loading,
    error,
    login,
    register,
    logout,
    isAuthenticated: !!token && !!user,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

