        const result = await collegeService.getColleges({ signal: controller.signal });
        if (result.success) {
          setColleges(result.data || []);
        }
      } catch (err: unknown) {
        const e = err as { __isCanceled?: boolean };
        if (!e.__isCanceled) {
          console.error('Error fetching colleges:', err);
        }
      }
    };
    fetchColleges();

    return () => controller.abort();
  }, []);

