          { collegeId: selectedCollegeId },
          { signal: controller.signal }
        );
        if (result.success) {
          setDepartments(result.data || []);
        }
      } catch (err: unknown) {
        const e = err as { __isCanceled?: boolean };
        if (!e.__isCanceled) {
          console.error('Error fetching departments:', err);
        }
