import React, { useState, useEffect } from 'react';
import coursesService from '../../services/courses.service';
import collegeService from '../../services/college.service';
import departmentService from '../../services/department.service';
import doctorsService from '../../services/doctors.service';
import Button from '../../components/ui/Button';
import Input from '../../components/ui/Input';
import { useTranslation } from 'react-i18next';
import {
  X,
  BookOpen,
  Hash,
  FileText,
  User,
  GraduationCap,
  School,
  AlertCircle,
  _CheckCircle,
  _Loader2,
} from 'lucide-react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';

const schema = z.object({
  name: z.string().min(1, 'Name is required'),
  courseCode: z.string().min(1, 'Course code is required'),
  description: z.string().optional(),
  credits: z.coerce.number().min(1, 'Min 1').max(10, 'Max 10'),
  maxStudents: z.coerce.number().min(1, 'Min 1'),
  departmentId: z.string().min(1, 'Department is required'),
  collegeId: z.string().min(1, 'College is required'),
  doctorId: z.string().optional(),
  year: z.coerce.number().min(1),
  semester: z.coerce.number().min(1),
});

type FormData = z.infer<typeof schema>;

const CourseModal = ({ isOpen, onClose, onSuccess, course }) => {
  const { _t } = useTranslation();
  const {
    register,
    handleSubmit,
    reset,
    watch,
    formState: { errors, isSubmitting },
  } = useForm<any>({
    resolver: zodResolver(schema) as unknown as Record<string, unknown>,
    defaultValues: {
      name: '',
      courseCode: '',
      description: '',
      credits: 3,
      maxStudents: 30,
      departmentId: '',
      collegeId: '',
      doctorId: '',
      year: 1,
      semester: 1,
    },
  });

  const [colleges, setColleges] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [doctors, setDoctors] = useState([]);
  const [_fetchingData, setFetchingData] = useState(false);
  const [error, setError] = useState(null);

  const watchCollegeId = watch('collegeId');

  useEffect(() => {
    if (watchCollegeId) {
      fetchDepartments(watchCollegeId);
    } else {
      setDepartments([]);
    }
  }, [watchCollegeId]);

  useEffect(() => {
    if (isOpen) {
      fetchInitialData();
      if (course) {
        reset({
          name: course.name || '',
          courseCode: course.courseCode || '',
          description: course.description || '',
          credits: course.credits || 3,
          maxStudents: course.maxStudents || 30,
          departmentId: course.departmentId || '',
          collegeId: course.department?.collegeId || '',
          doctorId: course.doctorId || '',
          year: course.year || 1,
          semester: course.semester || 1,
        });
      } else {
        reset({
          name: '',
          courseCode: '',
          description: '',
          credits: 3,
          maxStudents: 30,
          departmentId: '',
          collegeId: '',
          doctorId: '',
          year: 1,
          semester: 1,
        });
      }
    }
  }, [isOpen, course, reset]);

  const fetchInitialData = async () => {
    try {
      setFetchingData(true);
      const [collegesRes, doctorsRes] = await Promise.all([
        collegeService.getColleges(),
        doctorsService.getDoctors({ limit: 100 }),
      ]);

      if (collegesRes.success) setColleges(collegesRes.data);
      if (doctorsRes.success) setDoctors(doctorsRes.data.doctors || doctorsRes.data);
    } catch (err) {
      console.error('Error fetching modal data:', err);
    } finally {
      setFetchingData(false);
    }
  };

  const fetchDepartments = async (collegeId) => {
    if (!collegeId) {
      setDepartments([]);
      return;
    }
    try {
      const res = await departmentService.getDepartments({ collegeId });
      if (res.success) setDepartments(res.data);
    } catch (err) {
      console.error('Error fetching departments:', err);
    }
  };

  const onSubmit = async (data: FormData) => {
    setError(null);

    try {
      let res;
      if (course) {
        res = await coursesService.updateCourse(course.id, data);
      } else {
        res = await coursesService.createCourse(data);
      }

      if (res.success) {
        onSuccess();
      } else {
        setError(res.message || 'An error occurred');
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to save course');
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div
        className="absolute inset-0 bg-brand-navy-500/40 backdrop-blur-sm"
        onClick={onClose}
      ></div>

      <div className="relative bg-brand-bg-card dark:bg-brand-bg-elevated rounded-2xl shadow-2xl w-full max-w-2xl overflow-hidden animate-in zoom-in-95 duration-200">
        <div className="px-6 py-4 border-b border-brand-border dark:border-brand-border flex justify-between items-center bg-brand-bg-page/50 dark:bg-brand-bg-elevated/50">
          <div>
            <h2 className="text-xl font-bold text-brand-text-primary dark:text-brand-text-main">
              {course ? 'Edit Course' : 'Add New Course'}
            </h2>
            <p className="text-sm text-brand-text-secondary dark:text-brand-text-muted mt-0.5">
              {course
                ? 'Update course details and linking.'
                : 'Create a new course and link it to a department.'}
            </p>
          </div>
          <button
            onClick={onClose}
            className="p-2 text-brand-text-muted hover:text-brand-text-secondary dark:hover:text-brand-text-secondary hover:bg-brand-bg-page dark:hover:bg-brand-bg-elevated rounded-xl transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        <form
          onSubmit={handleSubmit((data: Record<string, unknown>) => onSubmit(data))}
          className="p-6 max-h-[80vh] overflow-y-auto"
        >
          {error && (
            <div className="mb-6 p-4 rounded-xl bg-error text-white flex items-center gap-2 animate-in slide-in-from-top-2 duration-300">
              <AlertCircle size={20} />
              <span className="font-medium">{error}</span>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
            <div className="md:col-span-2 space-y-1.5">
              <label className="text-sm font-semibold text-brand-text-primary dark:text-brand-text-secondary flex items-center gap-2 ml-1">
                <BookOpen size={14} className="text-brand-text-muted" /> Course Name{' '}
                <span className="text-error">*</span>
              </label>
              <Input {...register('name')} placeholder="e.g. Advanced Web Development" />
              {errors.name && <p className="text-rose-500 text-xs mt-1">{errors.name.message}</p>}
            </div>

            <div className="space-y-1.5">
              <label className="text-sm font-semibold text-brand-text-primary dark:text-brand-text-secondary flex items-center gap-2 ml-1">
                <Hash size={14} className="text-brand-text-muted" /> Course Code{' '}
                <span className="text-error">*</span>
              </label>
              <Input {...register('courseCode')} placeholder="e.g. CS302" />
              {errors.courseCode && (
                <p className="text-rose-500 text-xs mt-1">{errors.courseCode.message}</p>
              )}
            </div>

            <div className="space-y-1.5">
              <label className="text-sm font-semibold text-brand-text-primary dark:text-brand-text-secondary flex items-center gap-2 ml-1">
                <GraduationCap size={14} className="text-brand-text-muted" /> Credits{' '}
                <span className="text-error">*</span>
