import React, { useState, useEffect } from 'react';
import coursesService from '../../services/courses.service';
import doctorsService from '../../services/doctors.service';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';

const schema = z.object({
  name: z.string().min(1, 'Course Name is required'),
  description: z.string().optional(),
  credits: z.coerce
    .number()
    .min(1, 'Credits must be at least 1')
    .max(10, 'Credits must be at most 10'),
  maxStudents: z.coerce.number().min(1, 'Max students must be at least 1'),
  doctorId: z.string().optional(),
});

type FormData = z.infer<typeof schema>;

const EditCourseModal = ({ isOpen, onClose, onSuccess, course }) => {
  const [doctors, setDoctors] = useState([]);
  const [toast, setToast] = useState(null);

  const {
    register,
    handleSubmit,
    reset,
    formState: { errors, isSubmitting },
  } = useForm<any>({
    resolver: zodResolver(schema) as unknown as Record<string, unknown>,
  });

  useEffect(() => {
    if (isOpen) {
      fetchDoctors();
      if (course) {
        reset({
          name: course.name || '',
          description: course.description || '',
          credits: course.credits || 3,
          maxStudents: course.maxStudents || 30,
          doctorId: course.doctorId || '',
        });
      }
    }
  }, [isOpen, course, reset]);

  const fetchDoctors = async () => {
    try {
      const result = await doctorsService.getDoctors({ limit: 100 });
      if (result.success) {
        setDoctors(result.data.doctors);
      }
    } catch (error) {
      console.error('Error fetching doctors:', error);
    }
  };

  const showToast = (message, type) => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const onSubmit = async (data: FormData) => {
    try {
      const result = await coursesService.updateCourse(course.id, data);
      if (result.success) {
        onSuccess();
      }
    } catch (error) {
      showToast(error.response?.data?.message || 'Error updating course', 'error');
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm px-4 sm:px-6">
      <div className="bg-brand-bg-card dark:bg-brand-bg-elevated rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden transform transition-all max-h-[90vh] overflow-y-auto">
        <div className="px-6 py-4 border-b border-brand-border dark:border-brand-border flex justify-between items-center bg-brand-bg-page dark:bg-brand-bg-elevated/50">
          <h2 className="text-xl font-bold text-brand-text-primary dark:text-brand-text-main">
            Edit Course: {course?.courseCode}
          </h2>
          <button
            onClick={onClose}
            className="text-brand-text-muted hover:text-brand-text-secondary dark:text-brand-text-muted dark:hover:text-brand-text-secondary transition-colors"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth="2"
                d="M6 18L18 6M6 6l12 12"
              />
            </svg>
          </button>
        </div>

        <form
          onSubmit={handleSubmit((data: Record<string, unknown>) => onSubmit(data))}
          className="p-6"
        >
          {toast && (
            <div
