import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  _Calendar,
  _Clock,
  _MapPin,
  BookOpen,
  _User,
  _Building2,
  FileText,
  ArrowLeft,
  AlertCircle,
  Loader2,
  CheckCircle2,
  Download,
  _Info,
} from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../../context/AuthContext';
import examsService from '../../services/exams.service';
import Card from '../../components/ui/Card';
import Button from '../../components/ui/Button';
import Badge from '../../components/ui/Badge';

const ExamDetails = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { _t } = useTranslation();
  const { user } = useAuth();
  const [exam, setExam] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchExamDetails();
  }, [id]);

  const fetchExamDetails = async () => {
    try {
      setLoading(true);
      const result = await examsService.getExamById(id);
      if (result.success) {
        setExam(result.data);
      }
    } catch (err) {
      setError('Exam details could not be loaded.');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-96 gap-4">
        <Loader2 className="animate-spin text-brand-green" size={48} />
        <p className="text-brand-text-sub font-bold uppercase tracking-widest text-sm">
          Loading Exam Details...
        </p>
      </div>
    );
  }

  if (error || !exam) {
    return (
      <div className="text-center py-20 bg-brand-bg-card rounded-3xl border border-brand-border">
        <div className="h-20 w-20 rounded-full bg-brand-navy/5 flex items-center justify-center mx-auto mb-6">
