import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import examsService from '../../services/exams.service';
import coursesService from '../../services/courses.service';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../../context/AuthContext';
import useScope from '../../hooks/useScope';
import {
  _Plus,
  _Search,
  Calendar,
  Clock,
  MapPin,
  Filter,
  Trash2,
  _Eye,
  Loader2,
  CheckCircle2,
  AlertCircle,
} from 'lucide-react';
import { EmptyState } from '../../components/ui/EmptyState';
import { PageHeader } from '../../components/ui/PageHeader';
import Card from '../../components/ui/Card';
import Button from '../../components/ui/Button';
import Badge from '../../components/ui/Badge';
import Modal from '../../components/ui/Modal';
import Input from '../../components/ui/Input';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';

const schema = z.object({
  courseId: z.string().min(1, 'Course is required'),
  type: z.enum(['MIDTERM', 'FINAL', 'QUIZ']),
  date: z.string().min(1, 'Date is required'),
  startTime: z.string().min(1, 'Start time is required'),
  endTime: z.string().min(1, 'End time is required'),
  room: z.string().optional(),
});

type _FormData = z.infer<typeof schema>;

const AddExamModal = ({ isOpen, onClose, onSuccess }) => {
  const { t } = useTranslation();
  const [courses, setCourses] = useState([]);
  const [error, setError] = useState('');

  const {
    register,
    handleSubmit,
    reset,
    formState: { errors, isSubmitting },
  } = useForm({
    resolver: zodResolver(schema),
    defaultValues: {
      courseId: '',
      type: 'MIDTERM',
      date: '',
      startTime: '09:00',
      endTime: '11:00',
      room: '',
    },
  });

  useEffect(() => {
    if (isOpen) {
      fetchCourses();
      reset();
    }
  }, [isOpen, reset]);

  const fetchCourses = async () => {
    try {
      const result = await coursesService.getCourses();
      if (result.success) {
        // Handle both old array format and new paginated object format
        const coursesData = Array.isArray(result.data) ? result.data : result.data.courses;
        setCourses(coursesData || []);
      }
    } catch (err) {
      console.error(err);
    }
  };

  const onSubmit = async (data) => {
    setError('');
    try {
      const result = await examsService.createExam(data);
      if (result.success) {
        onSuccess();
        onClose();
      }
    } catch (err) {
      setError(err.response?.data?.message || t('exams.createError'));
    }
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
