// FIXED: Guard optional email when rendering admin rows (prevents intermittent blank page) - Phase 1
import React, { useState, useEffect } from 'react';
import Card from '../../components/ui/Card';
import { PageHeader } from '../../components/ui/PageHeader';
import Table, { TableRow, TableCell, ActionMenu } from '../../components/ui/Table';
import Badge from '../../components/ui/Badge';
import FilterBar from '../../components/ui/FilterBar';
import { Trash2, ShieldCheck, AlertCircle, CheckCircle, X, Loader2 } from 'lucide-react';
import usersService from '../../services/users.service';
import collegeService from '../../services/college.service';
import departmentService from '../../services/department.service';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../../context/AuthContext';
import MaskedEmail from '../../components/MaskedEmail';
import Input from '../../components/ui/Input';
import Button from '../../components/ui/Button';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';

const schema = z.object({
  email: z.string().email('Invalid email'),
  password: z.string().min(1, 'Password is required'),
  role: z.enum(['SUPER_ADMIN', 'COLLEGE_ADMIN', 'DEPARTMENT_ADMIN']),
  managedCollegeId: z.string().optional(),
  managedDepartmentId: z.string().optional(),
});

type _FormData = z.infer<typeof schema>;

const AdminModal = ({ isOpen, onClose, onSuccess, colleges }) => {
  const { t } = useTranslation();
  const [departments, setDepartments] = useState([]);
  const [toast, setToast] = useState(null);

  const {
    register,
    handleSubmit,
    reset,
    watch,
    setValue,
    formState: { errors, isSubmitting },
  } = useForm({
    resolver: zodResolver(schema),
    defaultValues: {
      email: '',
      password: '',
      role: 'SUPER_ADMIN',
      managedCollegeId: '',
      managedDepartmentId: '',
    },
  });

  const role = watch('role');
  const managedCollegeId = watch('managedCollegeId');

  useEffect(() => {
    if (isOpen) {
      reset();
    }
  }, [isOpen, reset]);

  useEffect(() => {
    if (managedCollegeId) {
      fetchDepartments(managedCollegeId);
    }
  }, [managedCollegeId]);

  const showToast = (message, type) => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const fetchDepartments = async (collegeId) => {
    try {
      const res = await departmentService.getDepartments({ collegeId });
      if (res.success) setDepartments(res.data);
    } catch (error) {
      console.error('Error fetching departments:', error);
    }
  };

  const onSubmit = async (data) => {
    try {
      const payload = {
        email: data.email,
        password: data.password,
        role: data.role,
        managedCollegeId: data.managedCollegeId || undefined,
        managedDepartmentId: data.managedDepartmentId || undefined,
      };
      const res = await usersService.createAdmin(payload);
      if (res.success) {
        onSuccess();
        onClose();
      }
    } catch (error) {
      showToast(error.response?.data?.message || t('admins.createError'), 'error');
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div
        className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm"
        onClick={onClose}
        role="button"
        tabIndex={0}
      ></div>
      <div className="relative bg-white dark:bg-slate-900 rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden animate-in zoom-in-95 duration-200 border border-slate-200 dark:border-slate-800">
        <div className="px-6 py-4 border-b border-brand-border dark:border-brand-border flex justify-between items-center bg-surface-subtle dark:bg-slate-800/50">
          <h2 className="text-xl font-bold text-slate-900 dark:text-white">{t('admins.addNew')}</h2>
          <button
            onClick={onClose}
            className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 rounded-xl transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit(onSubmit)} className="p-6 space-y-4">
          {toast && (
            <div
              className={`p-4 rounded-xl text-white flex items-center gap-2 ${toast.type === 'error' ? 'bg-rose-500' : 'bg-emerald-500'}`}
            >
              <AlertCircle size={20} />
              <span>{toast.message}</span>
            </div>
          )}

          <div className="space-y-1.5">
            <label className="text-sm font-semibold text-slate-700 dark:text-slate-300">
              {t('admins.email')}
            </label>
            <Input type="email" {...register('email')} placeholder="example@email.com" />
            {errors.email && <p className="text-rose-500 text-xs mt-1">{errors.email.message}</p>}
          </div>

          <div className="space-y-1.5">
            <label className="text-sm font-semibold text-slate-700 dark:text-slate-300">
              {t('admins.password')}
            </label>
            <Input type="password" {...register('password')} placeholder="••••••••" />
            {errors.password && (
              <p className="text-rose-500 text-xs mt-1">{errors.password.message}</p>
            )}
          </div>

          <div className="space-y-1.5">
            <label className="text-sm font-semibold text-slate-700 dark:text-slate-300">
              {t('admins.roleType')}
            </label>
            <select
              {...register('role', {
                onChange: () => {
                  setValue('managedCollegeId', '');
                  setValue('managedDepartmentId', '');
                },
              })}
              className="w-full px-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-blue-500/20 outline-none dark:text-white"
            >
              <option value="SUPER_ADMIN">{t('admins.roleSuperAdmin')}</option>
              <option value="COLLEGE_ADMIN">{t('admins.roleCollegeAdmin')}</option>
              <option value="DEPARTMENT_ADMIN">{t('admins.roleDeptAdmin')}</option>
            </select>
            {errors.role && <p className="text-rose-500 text-xs mt-1">{errors.role.message}</p>}
          </div>

          {(role === 'COLLEGE_ADMIN' || role === 'DEPARTMENT_ADMIN') && (
            <div className="space-y-1.5">
              <label className="text-sm font-semibold text-slate-700 dark:text-slate-300">
                {t('admins.college')}
              </label>
              <select
                {...register('managedCollegeId', {
                  onChange: () => setValue('managedDepartmentId', ''),
                })}
                className="w-full px-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl text-sm dark:text-white"
              >
                <option value="">{t('admins.selectCollege')}</option>
                {colleges.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name}
                  </option>
                ))}
              </select>
              {errors.managedCollegeId && (
                <p className="text-rose-500 text-xs mt-1">{errors.managedCollegeId.message}</p>
              )}
            </div>
          )}

          {role === 'DEPARTMENT_ADMIN' && (
            <div className="space-y-1.5">
              <label className="text-sm font-semibold text-slate-700 dark:text-slate-300">
                {t('admins.department')}
              </label>
              <select
                {...register('managedDepartmentId')}
                className="w-full px-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl text-sm dark:text-white"
              >
                <option value="">{t('admins.selectDepartment')}</option>
                {departments.map((d) => (
                  <option key={d.id} value={d.id}>
                    {d.name}
                  </option>
                ))}
              </select>
              {errors.managedDepartmentId && (
                <p className="text-rose-500 text-xs mt-1">{errors.managedDepartmentId.message}</p>
              )}
            </div>
          )}

          <div className="mt-8 flex justify-end gap-3 pt-6 border-t border-brand-border dark:border-brand-border">
            <Button type="button" variant="outline" onClick={onClose}>
              {t('common.cancel')}
            </Button>
            <Button type="submit" disabled={isSubmitting}>
              {t('admins.createAdmin')}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

const AdminsList = () => {
  const { t } = useTranslation();
  const { user } = useAuth();
  const [admins, setAdmins] = useState([]);
  const [colleges, setColleges] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [toast, setToast] = useState(null);

  useEffect(() => {
    fetchAdmins();
    fetchColleges();
  }, []);

  const ADMIN_ROLES = ['SUPER_ADMIN', 'ADMIN', 'COLLEGE_ADMIN', 'DEPARTMENT_ADMIN'];

  const fetchAdmins = async () => {
    try {
      setLoading(true);
      const res = await usersService.getUsers({ role: ADMIN_ROLES });
      if (res.success) {
        const list = Array.isArray(res.data) ? res.data : [];
        setAdmins(list.filter((u) => ADMIN_ROLES.includes(u.role)));
      }
    } catch (error) {
      console.error('Error fetching admins:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchColleges = async () => {
    try {
      const res = await collegeService.getColleges();
      if (res.success) setColleges(res.data);
    } catch (error) {
      console.error('Error fetching colleges:', error);
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm(t('admins.deleteConfirm'))) {
      try {
        const res = await usersService.deleteUser(id);
        if (res.success) {
          showToast(t('admins.deleteSuccess'), 'success');
          fetchAdmins();
        }
      } catch (error) {
        showToast(error.response?.data?.message || t('admins.deleteError'), 'error');
      }
    }
  };

  const showToast = (message, type) => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const filteredAdmins = (admins || []).filter((admin) =>
    (admin.email || '').toLowerCase().includes((search || '').toLowerCase())
  );

  return (
    <div className="section-gap animate-page">
      {toast && (
        <div className={`${toast.type === 'error' ? 'toast-error' : 'toast-success'}`}>
          <div className="flex items-center gap-2">
            {toast.type === 'error' ? <AlertCircle size={18} /> : <CheckCircle size={18} />}
            <span className="font-medium">{toast.message}</span>
          </div>
        </div>
      )}

      <PageHeader
        title={t('admins.title')}
        subtitle="UNIVERSITY, COLLEGE, AND DEPARTMENT ADMINISTRATORS"
        action={
          user?.role === 'SUPER_ADMIN'
            ? {
                label: 'Add Admin',
                onClick: () => setIsModalOpen(true),
              }
            : null
        }
      />

      <Card noPadding className="border-none shadow-soft overflow-hidden">
        <FilterBar
          search={search}
          onSearchChange={setSearch}
          searchPlaceholder="Search by email..."
        />

        <div className="min-h-[400px]">
          {loading ? (
            <div className="flex flex-col items-center justify-center h-64 gap-4">
              <Loader2 className="animate-spin text-brand-primary-500" size={40} />
              <p className="label-stat">Loading staff...</p>
            </div>
          ) : filteredAdmins.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-96 text-center p-8">
              <div className="w-24 h-24 rounded-[2.5rem] bg-surface-subtle dark:bg-surface-subtle flex items-center justify-center mb-6 border-2 border-dashed border-slate-200 dark:border-slate-700">
                <ShieldCheck size={48} className="text-brand-text-muted opacity-50" />
              </div>
              <h3 className="text-2xl font-black text-brand-text-primary dark:text-brand-text-main tracking-tight uppercase mb-2">
                No Admins Found
              </h3>
              <p className="text-brand-text-secondary font-bold max-w-xs mx-auto">
                Try adjusting your search terms.
              </p>
            </div>
          ) : (
            <Table headers={['Admin', 'Role', 'Affiliation', 'Joined', 'Actions']}>
              {filteredAdmins.map((admin) => (
                <TableRow key={admin.id}>
                  <TableCell>
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 rounded-xl bg-brand-navy-50 dark:bg-brand-navy-900/10 flex items-center justify-center text-brand-navy-500 font-black shadow-inner">
                        <ShieldCheck size={20} />
                      </div>
                      <div className="flex flex-col">
                        <span className="font-black text-brand-text-primary dark:text-brand-text-main tracking-tight">
                          {(admin.email || 'admin').split('@')[0]}
                        </span>
                        <MaskedEmail email={admin.email} />
                      </div>
                    </div>
                  </TableCell>
                  <TableCell>
                    <Badge
                      variant={
                        admin.role === 'SUPER_ADMIN'
                          ? 'danger'
                          : admin.role === 'COLLEGE_ADMIN'
                            ? 'primary'
                            : 'warning'
                      }
                      className="px-3 py-1 text-[10px] font-black uppercase tracking-widest"
                    >
                      {admin.role.replace('_', ' ')}
                    </Badge>
                  </TableCell>
                  <TableCell>
                    <div className="flex flex-col">
                      <span className="text-xs font-black text-brand-text-primary dark:text-brand-text-main uppercase tracking-tight truncate max-w-[180px]">
                        {admin.managedCollege?.name || admin.college?.name || 'All University'}
                      </span>
                      {admin.department && (
                        <span className="text-[10px] font-bold text-brand-text-secondary uppercase truncate max-w-[150px]">
                          {admin.department.name}
                        </span>
                      )}
                    </div>
                  </TableCell>
                  <TableCell className="label-stat">
                    {new Date(admin.createdAt).toLocaleDateString()}
                  </TableCell>
                  <TableCell>
                    {user?.role === 'SUPER_ADMIN' && admin.id !== user.id ? (
                      <ActionMenu
                        actions={[
                          {
                            label: 'Delete',
                            icon: Trash2,
                            variant: 'delete',
                            onClick: () => handleDelete(admin.id),
                          },
                        ]}
                      />
                    ) : null}
                  </TableCell>
                </TableRow>
              ))}
            </Table>
          )}
        </div>
      </Card>

      <AdminModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSuccess={fetchAdmins}
        colleges={colleges}
      />
    </div>
  );
};

export default AdminsList;

