        firstName: student.firstName || '',
        lastName: student.lastName || '',
        phone: student.phone || '',
        address: student.address || '',
        studentId: student.studentId || '',
        year: student.year || 1,
        departmentId: student.departmentId || undefined,
        collegeId: student.department?.collegeId || undefined,
